fn now_ms() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)?
        .as_millis()
        .try_into()?)
}

fn submit(
    root: &Root,
    signer: &KeyPair,
    instructions: Vec<InstructionBox>,
    rt: &tokio::runtime::Runtime,
) -> Result<iroha_data_model::sumeragi_finality::VerifiedSumeragiBlock> {
    let client = root.client(signer);
    let account = client.account_client();
    let payload = account.prepare_transaction(AccountTransactionDraft::new(
        instructions,
        fee_intent(),
        Metadata::default(),
    ))?;
    let transaction = account.sign_transaction(payload)?;
    let hash = transaction.hash();
    rt.block_on(account.submit_transaction(&transaction))?;
    let mut verifier = root.verifier()?;
    rt.block_on(async {
        tokio::time::timeout(Duration::from_secs(180), async {
            loop {
                let height = client.client().status().get().await?.blocks;
                let next = verifier.authenticated_height().unwrap_or(0) + 1;
                ensure!(
                    height.saturating_sub(next) < 128,
                    "bootstrap history unexpectedly grew"
                );
                for height in next..=height {
                    let proof = client
                        .client()
                        .get_sumeragi_finality_proof_async(
                            NonZeroU64::new(height).unwrap(),
                            root.scope,
                        )
                        .await?;
                    let verified = verifier.verify(&proof)?;
                    let index = verified.block().network_entrypoints().position(|entry| {
                        matches!(entry, TransactionEntrypoint::External(signed) if signed.hash() == hash)
                    });
                    if let Some(index) = index {
                        verified.verify_committed_transaction(
                            &root.network.network_id(),
                            &proofs::evidence(verified.block(), index.try_into()?)?,
                        )?;
                        return Ok(verified);
                    }
                }
                tokio::time::sleep(Duration::from_millis(200)).await;
            }
        })
        .await
    })?
    .map_err(Into::into)
}

// Complete parent acquisition before child genesis executes on this same ordinary stack.
// Keeping full finality proofs/verifiers in Exchange::start would retain their large
// unoptimized frame throughout native registration. This helper returns only the
// original canonical wires after exactly the same signed-genesis and H2 joins.
fn parent_registration_sources(
    global: &Root,
    runtime: &tokio::runtime::Runtime,
) -> Result<(Vec<u8>, Vec<u8>)> {
    let successor = submit(
        global,
        &genesis_key(0),
        vec![
            Transfer::asset_quantity(
                AssetId::of(fee_asset(), account(&genesis_key(0))),
                1_u32,
                account(&relay(0)),
            )
            .into(),
        ],
        runtime,
    )?;
    ensure!(
        successor.height() == 2,
        "parent bootstrap must be the actual H2 transfer"
    );
    // Signed bootstrap H1 authenticates the initial authority but carries no native
    // execution result. Registration needs the original executed H1 from Kura and
    // its real H2 successor. Independently verify both before authoring either child.
    let client = global.client(&relay(0));
    let mut parent_verifier = global.verifier()?;
    let parent_genesis = runtime.block_on(
        client
            .client()
            .get_sumeragi_finality_proof_async(NonZeroU64::new(1).unwrap(), global.scope),
    )?;
    let parent_genesis = parent_verifier.verify(&parent_genesis)?;
    let parent_successor = runtime.block_on(
        client
            .client()
            .get_sumeragi_finality_proof_async(NonZeroU64::new(2).unwrap(), global.scope),
    )?;
    let parent_successor = parent_verifier.verify(&parent_successor)?;
    ensure!(
        parent_successor.context_id() == successor.context_id(),
        "registration must retain the original paid bootstrap execution"
    );
    ensure!(parent_genesis.block().hash() == global.pins.genesis_hash);
    ensure!(
        parent_genesis.block().commit_certificate().is_some(),
        "registration requires the executed H1 result-bearing source"
    );
    let genesis = parent_genesis.block().encode_wire()?;
    let successor = parent_successor.block().encode_wire()?;
    Ok((genesis, successor))
}

struct ExchangeReceipt {
    deliveries: [Option<(
        u64,
        iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
    )>; 2],
    decisions: [Option<iroha_data_model::sumeragi_amx::AmxCertifiedBlockV1>; 2],
}

struct Exchange {
    roots: [Root; 3],
    runtime: tokio::runtime::Runtime,
    custody: std::path::PathBuf,
}
impl Exchange {
    fn start() -> Result<Self> {
        let permits = std::env::var("IROHA_TEST_NETWORK_PARALLELISM")
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(1);
        ensure!(
            permits >= 3 && std::env::var_os("IROHA_TEST_SERIALIZE_NETWORKS").is_none(),
            "12-validator AMX acceptance requires IROHA_TEST_NETWORK_PARALLELISM=3, IROHA_TEST_SERIALIZE_NETWORKS unset, isolated IROHA_TEST_NETWORK_PERMIT_DIR and --test-threads=1"
        );
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .build()?;
        let global = Root::new(0, None)?;
        runtime.block_on(global.network.start_all())?;
        let (genesis, successor) = parent_registration_sources(&global, &runtime)?;
        let first = Root::new(1, Some((&global, genesis.clone(), successor.clone())))?;
        let second = Root::new(2, Some((&global, genesis, successor)))?;
        runtime.block_on(first.network.start_all())?;
        runtime.block_on(second.network.start_all())?;
        runtime.block_on(first.assert_listener_authentication(&second))?;
        runtime.block_on(second.assert_listener_authentication(&first))?;
        submit(
            &global,
            &genesis_key(0),
            vec![first.registry()?.into(), second.registry()?.into()],
            &runtime,
        )?;
        // Retain relay signing inputs and journals with the Global peer stores.
        let custody = tempfile::tempdir_in(global.network.env_dir())?.keep();
        let global_route = route(&global, custody.as_path())?;
        let first_route = route(&first, custody.as_path())?;
        let second_route = route(&second, custody.as_path())?;
        let mut roots = [global, first, second];
        roots[0].relay_layer = service(
            custody.as_path(),
            0,
            vec![global_route.clone(), first_route, second_route],
        );
        roots[1].relay_layer = service(custody.as_path(), 1, vec![global_route.clone()]);
        roots[2].relay_layer = service(custody.as_path(), 2, vec![global_route]);
        for root in &roots {
            runtime.block_on(root.restart_service())?;
        }
        for root in &roots {
            ensure!(root.network.validators().len() == 4 && root.pins.roster.len() == 4);
        }
        ensure!(
            roots[0].network.network_id() != roots[1].network.network_id()
                && roots[1].network.network_id() != roots[2].network.network_id()
        );
        ensure!(currency(0) != currency(1));
        ensure!(account(&payer(0)) != account(&payer(1)));
        ensure!((0..2).all(|bank| account(&payer(bank)) != account(&relay(bank + 1))));
        Ok(Self {
            roots,
            runtime,
            custody,
        })
    }
    fn begin(
        &self,
        seconds_until_expiry: u64,
        nonce: u8,
        stop_second_bank: bool,
    ) -> Result<(AmxTransactionV1, [AmxDebitApprovalV1; 2])> {
        let global = &self.roots[0];
        let height = self
            .runtime
            .block_on(global.client(&relay(0)).client().status().get())?
            .blocks;
        let transaction = AmxTransactionV1 {
            legs: (0..2)
                .map(|bank| {
                    Ok(AmxLegV1 {
                        dataspace: DATASPACES[bank],
                        payload: norito::encode_canonical(&AmxTransferLegV1 {
                            source: AssetId::with_scope(
                                currency(bank),
                                account(&payer(bank)),
                                AssetBalanceScope::Dataspace(DATASPACES[bank]),
                            ),
                            destination: account(&payer(1 - bank)),
                            amount: Quantity::from([125_u32, 250_u32][bank]),
                        })?,
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            deadline: height + 500,
            expires_at_ms: now_ms()?.checked_add(seconds_until_expiry * 1000).unwrap(),
            nonce: [nonce; 32],
        };
        let tx = transaction.id()?;
        let approvals = [0, 1].map(|bank| AmxDebitApprovalV1 {
            global_network: global.network.network_id(),
            participant_network: self.roots[bank + 1].network.network_id(),
            participant_instance: self.roots[bank + 1].instance,
            dataspace: DATASPACES[bank],
            transaction_id: tx,
            debited_asset: AssetId::with_scope(
                currency(bank),
                account(&payer(bank)),
                AssetBalanceScope::Dataspace(DATASPACES[bank]),
            ),
        });
        for bank in 0..2 {
            submit(
                &self.roots[bank + 1],
                &payer(bank),
                vec![
                    Grant::account_permission(
                        approvals[bank].permission()?,
                        account(&relay(bank + 1)),
                    )
                    .into(),
                ],
                &self.runtime,
            )?;
        }
        if stop_second_bank {
            // The configured route remains present. Its actual transport and all
            // four validators disappear only after the original owner consent is durable.
            self.runtime.block_on(self.roots[2].network.shutdown());
        }
        submit(
            global,
            &genesis_key(0),
            vec![
                BeginAmxV1 {
                    transaction: transaction.clone(),
                }
                .into(),
            ],
            &self.runtime,
        )?;
        Ok((transaction, approvals))
    }
    fn observe(
        &self,
        transaction: &AmxTransactionV1,
        approvals: &[AmxDebitApprovalV1; 2],
        outcome: AmxOutcomeV1,
        required_banks: [bool; 2],
    ) -> Result<ExchangeReceipt> {
        let mut observers = [
            Observer::new(&self.roots[1], &self.roots[0])?,
            Observer::new(&self.roots[2], &self.roots[0])?,
        ];
        let tx = transaction.id()?;
        let mut unavailable = [
            "no successful authenticated decision carrier".to_owned(),
            "no successful authenticated decision carrier".to_owned(),
        ];
        let result = self.runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(240), async {
                let mut heights = [0; 2];
                loop {
                    for bank in 0..2 {
                        if !required_banks[bank] {
                            continue;
                        }
                        observers[bank].refresh(&self.roots[bank + 1], tx).await?;
                        if observers[bank].decision != Some(outcome) {
                            continue;
                        }
                        let proof = match observers[bank]
                            .world(&self.roots[bank + 1], &approvals[bank])
                            .await
                        {
                            Ok(proof) => proof,
                            Err(error) => {
                                // A moving cut is retryable, never absence; retain its real cause.
                                unavailable[bank] = format!("bank cut: {error:?}");
                                continue;
                            }
                        };
                        let moved = if outcome == AmxOutcomeV1::Commit {
                            [125, 250][bank]
                        } else {
                            0
                        };
                        if let Err(error) =
                            observers[bank].balances(&proof, bank, PRINCIPAL - moved, moved, 0)
                        {
                            unavailable[bank] = format!("monetary evidence: {error:?}");
                        } else {
                            heights[bank] = observers[bank].tip.as_ref().unwrap().height();
                            std::fs::write(
                                self.custody
                                    .as_path()
                                    .join(format!("bank-{bank}-world.nrt")),
                                norito::encode_canonical(&proof)?,
                            )?;
                            std::fs::write(
                                self.custody
                                    .as_path()
                                    .join(format!("bank-{bank}-finality.nrt")),
                                norito::encode_canonical(observers[bank].proof.as_ref().unwrap())?,
                            )?;
                        }
                    }
                    if heights
                        .iter()
                        .enumerate()
                        .all(|(bank, height)| !required_banks[bank] || *height > 0)
                    {
                        return Ok(ExchangeReceipt {
                            deliveries: std::array::from_fn(|bank| observers[bank].delivery),
                            decisions: std::array::from_fn(|bank| {
                                observers[bank].decision_source.clone()
                            }),
                        });
                    }
                    tokio::time::sleep(Duration::from_millis(200)).await;
                }
            })
            .await
        });
        result.map_err(|error| {
            eyre!("independent settlement evidence deadline: {error}; {unavailable:?}")
        })?
    }
    fn wait_for_first_escrow(
        &self,
        transaction: &AmxTransactionV1,
        approval: &AmxDebitApprovalV1,
    ) -> Result<()> {
        let mut observer = Observer::new(&self.roots[1], &self.roots[0])?;
        let mut unavailable = "no authenticated escrow cut".to_owned();
        let result = self.runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(90), async {
                loop {
                    observer.refresh(&self.roots[1], transaction.id()?).await?;
                    match observer.world(&self.roots[1], approval).await {
                        Ok(proof) => match observer.balances(&proof, 0, PRINCIPAL - 125, 0, 125) {
                            Ok(()) => return Ok(()),
                            Err(error) => unavailable = format!("escrow balance: {error:?}"),
                        },
                        Err(error) => unavailable = format!("escrow cut: {error:?}"),
                    }
                    tokio::time::sleep(Duration::from_millis(200)).await;
                }
            })
            .await
        });
        result.map_err(|error| eyre!("escrow acquisition deadline: {error}; {unavailable}"))?
    }

    // A successful local Prepare does not prove Global has consumed the Yes. The
    // pre-expiry case excludes a delayed Prepared carrier as the later Abort trigger.
    fn global_progress(
        &self,
        transaction: &AmxTransactionV1,
        expiry: bool,
    ) -> Result<iroha_data_model::sumeragi_finality::VerifiedSumeragiBlock> {
        use iroha_data_model::{
            isi::sumeragi_amx::{ExpireAmxV1, RelayAmxPreparedV1},
            sumeragi_amx::{AmxRecordV1, AmxVoteV1},
            transaction::Executable,
        };
        let root = &self.roots[0];
        let client = root.client(&relay(0));
        let mut verifier = root.verifier()?;
        let tx = transaction.id()?;
        self.runtime.block_on(async { tokio::time::timeout(Duration::from_secs(240), async {
            loop {
                let tip = client.client().status().get().await?.blocks;
                for height in verifier.authenticated_height().unwrap_or(0) + 1..=tip {
                    let proof = client.client().get_sumeragi_finality_proof_async(NonZeroU64::new(height).unwrap(), root.scope).await?;
                    let block = verifier.verify(&proof)?;
                    let mut progressed = false;
                    for (index, entry) in block.block().network_entrypoints().enumerate() {
                        let TransactionEntrypoint::External(signed) = entry else { continue; };
                        let Executable::Instructions(instructions) = signed.instructions() else { continue; };
                        let selected = instructions.iter().any(|instruction| {
                            if expiry {
                                instruction.as_any().downcast_ref::<ExpireAmxV1>().is_some_and(|value| value.tx == tx)
                            } else {
                                instruction.as_any().downcast_ref::<RelayAmxPreparedV1>().is_some_and(|value| matches!(&value.proof.record,
                                    AmxRecordV1::Prepared(prepared) if prepared.tx == tx && prepared.participant == DATASPACES[0] && matches!(&prepared.vote, AmxVoteV1::Yes(_))))
                            }
                        });
                        if !selected { continue; }
                        let carrier = proofs::evidence(block.block(), index.try_into()?)?;
                        block.verify_transaction_execution(&root.network.network_id(), &carrier)?;
                        if !carrier.output.result().is_ok() { continue; }
                        ensure!(signed.authority() == &account(&relay(0)), "the actual service fee account must submit Global progress");
                        let fee = carrier.output.result().nexus_fee_receipt().ok_or_else(|| eyre!("Global service carrier lacks a fee receipt"))?;
                        ensure!(fee.debit_source == iroha_data_model::nexus::FeeDebitSource::Account(account(&relay(0))) && fee.fee_asset_id == fee_asset() && !fee.fee_amount.is_zero());
                        ensure!(fee.dataspace_id == DataSpaceId::UNIVERSAL && fee.block_height == block.height());
                        let time = block.header().creation_time_ms;
                        if expiry {
                            ensure!(time >= transaction.expires_at_ms && block.height() < transaction.deadline, "autonomous signed-time expiry must precede the height deadline");
                        } else {
                            ensure!(time < transaction.expires_at_ms, "first Yes must be consumed before signed-time expiry");
                        }
                        progressed = true;
                        break;
                    }
                    if progressed { return Ok(block); }
                }
                tokio::time::sleep(Duration::from_millis(200)).await;
            }
        }).await })?
    }

    // Only status polling schedules this bounded drain of already authorized carriers.
    // It supplies no work to consensus and never authenticates a monetary outcome.
    fn quiescent_heights(&self) -> Result<[u64; 3]> {
        self.runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(120), async {
                let mut previous = None;
                let mut stable_since = tokio::time::Instant::now();
                loop {
                    let mut heights = [0; 3];
                    let mut aligned = true;
                    for (index, root) in self.roots.iter().enumerate() {
                        for (peer_index, peer) in root.network.validators().iter().enumerate() {
                            let height = peer.status().await?.blocks;
                            if peer_index == 0 {
                                heights[index] = height;
                            } else {
                                aligned &= height == heights[index];
                            }
                        }
                    }
                    if !aligned || previous != Some(heights) {
                        stable_since = tokio::time::Instant::now();
                        previous = Some(heights);
                    } else if stable_since.elapsed() >= Duration::from_secs(3) {
                        return Ok(heights);
                    }
                    tokio::time::sleep(Duration::from_millis(200)).await;
                }
            })
            .await
        })?
    }
    fn resume_second_bank(&self) -> Result<()> {
        self.runtime.block_on(async {
            self.roots[2].network.start_all().await?;
            self.roots[2].restart_service().await
        })
    }
    fn audit_fees(&self, heights: [u64; 3]) -> Result<()> {
        for (root, height) in self.roots.iter().zip(heights) {
            fees::audit(root, height, &self.runtime)?;
        }
        Ok(())
    }
    fn assert_no_background_blocks(&self, heights: [u64; 3]) -> Result<()> {
        self.runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let mut ready = true;
                    for (index, root) in self.roots.iter().enumerate() {
                        for peer in root.network.validators() {
                            match peer.status().await {
                                Ok(status) if status.blocks >= heights[index] => {}
                                _ => ready = false,
                            }
                        }
                    }
                    if ready {
                        break;
                    }
                    tokio::time::sleep(Duration::from_millis(200)).await;
                }
            })
            .await?;
            let until = tokio::time::Instant::now() + Duration::from_secs(3);
            while tokio::time::Instant::now() < until {
                for (index, root) in self.roots.iter().enumerate() {
                    for peer in root.network.validators() {
                        ensure!(
                            peer.status().await?.blocks == heights[index],
                            "final settlement recovery must not produce unrelated blocks"
                        );
                    }
                }
                tokio::time::sleep(Duration::from_millis(200)).await;
            }
            Ok(())
        })
    }
}
impl Drop for Exchange {
    fn drop(&mut self) {
        for root in &self.roots {
            self.runtime.block_on(root.network.shutdown());
        }
    }
}

#[test]
#[ignore = "12 validators across 3 roots; set IROHA_TEST_NETWORK_PARALLELISM=3 and use isolated permits with --test-threads=1"]
fn autonomous_two_bank_paid_pvp_survives_all_root_restart_without_successor_traffic() -> Result<()>
{
    let exchange = Exchange::start()?;
    let (transaction, approvals) = exchange.begin(300, 0xA1, false)?;
    let first = exchange.observe(&transaction, &approvals, AmxOutcomeV1::Commit, [true; 2])?;
    let heights = exchange.quiescent_heights()?;
    exchange.audit_fees(heights)?;
    for root in &exchange.roots {
        exchange.runtime.block_on(root.restart_all())?;
    }
    let recovered = exchange.observe(&transaction, &approvals, AmxOutcomeV1::Commit, [true; 2])?;
    ensure!(
        first.deliveries == recovered.deliveries,
        "restart must reverify the exact original successful settlement carriers"
    );
    exchange.audit_fees(heights)?;
    exchange.assert_no_background_blocks(heights)
}

#[test]
#[ignore = "12 validators across 3 roots; set IROHA_TEST_NETWORK_PARALLELISM=3 and use isolated permits with --test-threads=1"]
fn autonomous_final_silent_bank_aborts_after_relay_restart_and_releases_original_escrow()
-> Result<()> {
    let exchange = Exchange::start()?;
    let (transaction, approvals) = exchange.begin(120, 0xA2, true)?;
    exchange.wait_for_first_escrow(&transaction, &approvals[0])?;
    exchange.global_progress(&transaction, false)?;
    ensure!(
        now_ms()? < transaction.expires_at_ms,
        "setup exhausted signed expiry before restart"
    );
    let before = exchange
        .runtime
        .block_on(exchange.roots[0].client(&relay(0)).client().status().get())?
        .blocks;
    ensure!(
        before < transaction.deadline,
        "height timeout cannot decide this final idle payment"
    );
    // The only Global relay is stopped and resumed from its durable State/archive/workflow
    // owners. No test thread submits Expire, Prepared, Settle, Log or an empty block.
    exchange.runtime.block_on(exchange.roots[0].restart_all())?;
    // Bank A independently verifies the Global Abort and its actual refund while
    // all four bank B validators remain stopped behind a configured delivery route.
    // Its stalled transport must not block the Global expiry or bank A's refund.
    // Restarting B supplies no ledger work; the same service delivers the original decision.
    let abort = exchange.observe(&transaction, &approvals, AmxOutcomeV1::Abort, [true, false])?;
    let expiry = exchange.global_progress(&transaction, true)?;
    let certificate = expiry
        .block()
        .commit_certificate()
        .ok_or_else(|| eyre!("actual Expire carrier has no certificate"))?;
    let original_abort = abort.decisions[0].as_ref().unwrap();
    ensure!(
        original_abort.consensus_header == certificate.consensus_header()
            && original_abort.result_preimage == certificate.result_preimage(),
        "the original certified Abort must be produced by the exact successful autonomous Expire carrier"
    );
    exchange.resume_second_bank()?;
    exchange.observe(&transaction, &approvals, AmxOutcomeV1::Abort, [true; 2])?;
    let after = exchange.quiescent_heights()?;
    exchange.audit_fees(after)?;
    ensure!(
        after[0] < transaction.deadline,
        "certified time closure must decide before height expiry"
    );
    exchange.assert_no_background_blocks(after)
}
